(()=>{'use strict';
const modes=[['off','Off','No background effect','<circle cx="12" cy="12" r="8"/><path d="m6 6 12 12"/>'],['snow','Snow','Light drifting snow','<path d="M12 2v20M3 7l18 10M3 17 18 7M8 4l4 4 4-4M8 20l4-4 4 4"/>'],['stars','Stars','Twinkling stars and shooting stars','<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>'],['rain','Rain','Soft falling rain','<path d="M6 13a4 4 0 0 1 0-8 6 6 0 0 1 11 1 4 4 0 0 1 0 8M7 17l-2 4m8-4-2 4m8-4-2 4"/>'],['fireflies','Fireflies','Warm lights drifting slowly','<circle cx="12" cy="14" r="4"/><path d="m9 6 3 4 3-4M3 12h3m12 0h3M5 20l3-3m8 0 3 3"/>'],['petals','Petals','Floating pink petals','<path d="M12 12C1 13 4 1 10 5c4-9 12-2 6 4 10 1 5 12-2 7-2 10-12 4-7-2Z"/>'],['bubbles','Bubbles','Gentle rising bubbles','<circle cx="9" cy="15" r="6"/><circle cx="18" cy="6" r="3"/><path d="M6 14a3 3 0 0 1 3-2"/>'],['embers','Embers','Soft rising sparks','<path d="M13 2c2 6-3 6-1 10 2-1 3-3 3-3 7 8 2 13-3 13S2 17 6 11c0 4 3 4 3 4-2-5 3-7 4-13Z"/>'],['confetti','Confetti','Small Catppuccin color flecks','<path d="m3 21 4-13 9 9-13 4Zm8-16 1-3m5 5 4-2m-3 8 4 1M5 4 3 2m13 0 1 2"/>']];
window.TrackwhalesEffects={mount(){
const button=document.createElement('button');button.type='button';button.id='effectsPicker';button.className='theme-picker';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','effectsMenu');document.querySelector('#themePicker')?.after(button);
const menu=document.createElement('div');menu.id='effectsMenu';menu.className='theme-menu effects-menu';menu.hidden=true;menu.innerHTML='<p>Atmosphere</p>';document.body.append(menu);
const layer=document.createElement('div');layer.className='effects-layer';layer.setAttribute('aria-hidden','true');document.body.append(layer);
const icon=path=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">'+path+'</svg>';
let current='off';try{current=localStorage.getItem('trackwhales-effect')||(localStorage.getItem('trackwhales-snow')==='on'?'snow':'off')}catch{}
if(!modes.some(m=>m[0]===current))current='off';
function close(){menu.hidden=true;button.setAttribute('aria-expanded','false')}
function apply(mode){current=mode;const info=modes.find(m=>m[0]===mode);button.innerHTML=icon(info[3]);button.title='Atmosphere: '+info[1];button.setAttribute('aria-label','Choose atmosphere effect. Current: '+info[1]);layer.dataset.effect=mode;layer.hidden=mode==='off';layer.replaceChildren();for(const b of menu.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.effect===mode));if(mode==='off')return;const count=mode==='rain'?48:mode==='stars'?32:24;for(let i=0;i<count;i++){const particle=document.createElement('i');particle.className='effect-particle';particle.style.cssText=`--x:${Math.random()*100}%;--y:${Math.random()*100}%;--delay:-${Math.random()*30}s;--duration:${mode==='rain'?1+Math.random():12+Math.random()*18}s;--drift:${Math.random()*120-60}px;--size:${2+Math.random()*3}px;--twinkle:${2+Math.random()*5}s;--tone:var(--${['pink','mauve','blue','yellow','green'][i%5]})`;layer.append(particle)}if(mode==='stars')for(let i=0;i<3;i++){const star=document.createElement('i');star.className='shooting-star';star.style.cssText=`left:${15+Math.random()*70}%;top:${Math.random()*50}%;animation-delay:${i*5}s;animation-duration:${15+i*3}s`;layer.append(star)}}
for(const [name,label,description,path]of modes){const choice=document.createElement('button');choice.type='button';choice.className='effect-choice';choice.dataset.effect=name;choice.innerHTML=icon(path)+'<span><b>'+label+'</b><small>'+description+'</small></span><em>✓</em>';choice.addEventListener('click',()=>{apply(name);try{localStorage.setItem('trackwhales-effect',name)}catch{}close();button.focus()});menu.append(choice)}
button.addEventListener('click',()=>{if(!menu.hidden){close();return}menu.hidden=false;const r=button.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(innerWidth-252,r.right-244))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-menu.offsetHeight-8,r.bottom+7))+'px';button.setAttribute('aria-expanded','true')});document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target)&&!button.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});addEventListener('resize',close);document.addEventListener('visibilitychange',()=>layer.classList.toggle('effects-paused',document.hidden));apply(current);
}};
})();
